/** The error emit throws when listeners failed. */

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Errors thrown by listeners during one emit; every listener was still called. */
export class EmitError extends Error {
  /** The event whose listeners failed. */
  readonly event: string;
  /** What the failing listeners threw, in the order they were called. */
  readonly errors: readonly unknown[];

  constructor(event: string, errors: readonly unknown[]) {
    const count = errors.length === 1 ? "1 listener" : `${errors.length} listeners`;
    super(`${count} of ${JSON.stringify(event)} failed: ${errors.map(describe).join("; ")}`);
    this.name = "EmitError";
    this.event = event;
    this.errors = errors;
  }
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { Emitter } from "../src/emitter.ts";
import { EmitError } from "../src/errors.ts";

type Events = { refreshed: string };

test("the other listeners are still called when one throws", () => {
  const bus = new Emitter<Events>();
  const calls: string[] = [];
  bus.on("refreshed", () => {
    throw new Error("widget crashed");
  });
  bus.on("refreshed", (source) => calls.push(source));
  assert.throws(() => bus.emit("refreshed", "billing"), EmitError);
  assert.deepEqual(calls, ["billing"]);
});

test("the EmitError holds every error in order", () => {
  const bus = new Emitter<Events>();
  const first = new Error("first");
  bus.on("refreshed", () => {
    throw first;
  });
  bus.on("refreshed", () => {});
  bus.on("refreshed", () => {
    throw "second";
  });
  assert.throws(
    () => bus.emit("refreshed", "x"),
    (error: unknown) => {
      assert.ok(error instanceof EmitError);
      assert.equal(error.event, "refreshed");
      assert.deepEqual(error.errors, [first, "second"]);
      return true;
    },
  );
});

test("the message names the event and the errors", () => {
  assert.equal(
    new EmitError("refreshed", [new Error("boom")]).message,
    '1 listener of "refreshed" failed: boom',
  );
  assert.equal(
    new EmitError("saved", [new Error("a"), "b"]).message,
    '2 listeners of "saved" failed: a; b',
  );
});

test("an emit without errors does not throw", () => {
  const bus = new Emitter<Events>();
  bus.on("refreshed", () => {});
  assert.doesNotThrow(() => bus.emit("refreshed", "x"));
});

/** Wait for the next emit of an event, with a time limit. */

import type { Emitter } from "./emitter.ts";
import type { EventMap } from "./types.ts";

/** The event did not come within the time limit. */
export class WaitTimeoutError extends Error {
  readonly event: string;

  constructor(event: string, timeoutMs: number) {
    super(`no ${JSON.stringify(event)} event within ${timeoutMs} ms`);
    this.name = "WaitTimeoutError";
    this.event = event;
  }
}

/**
 * Resolve with the payload of the next emit of ``event``, or reject with a
 * WaitTimeoutError after ``timeoutMs``. The listener is removed either way.
 */
export function waitFor<Events extends EventMap, K extends keyof Events & string>(
  bus: Emitter<Events>,
  event: K,
  timeoutMs = 5000,
): Promise<Events[K]> {
  return new Promise((resolve, reject) => {
    const stop = bus.on(event, (payload) => {
      stop();
      clearTimeout(timer);
      resolve(payload);
    });
    const timer = setTimeout(() => {
      stop();
      reject(new WaitTimeoutError(event, timeoutMs));
    }, timeoutMs);
  });
}

/** The events of the operations dashboard; plugins may listen to all of them. */

import { Emitter } from "./emitter.ts";

/** Every dashboard event and its payload. */
export type DashboardEvents = {
  "widget:added": { widgetId: string; kind: string };
  "widget:removed": { widgetId: string };
  "layout:saved": { layoutId: string; widgets: number };
  "data:refreshed": { source: string; rows: number };
};

/** The names of the dashboard events, in the order the documentation lists them. */
export const DASHBOARD_EVENTS: readonly (keyof DashboardEvents)[] = [
  "widget:added",
  "widget:removed",
  "layout:saved",
  "data:refreshed",
];

/** A new, empty bus for the dashboard events. */
export function createDashboardBus(): Emitter<DashboardEvents> {
  return new Emitter<DashboardEvents>();
}

/** Re-emit events of one bus on another, for example from a plugin's own bus to the dashboard's. */

import type { Emitter } from "./emitter.ts";
import type { EventMap, Unsubscribe } from "./types.ts";

/**
 * Re-emit every listed event of ``from`` on ``to`` with the same payload, and return a
 * function that stops forwarding. Errors of the listeners on ``to`` reach the code that
 * emitted on ``from``.
 */
export function forward<Events extends EventMap>(
  from: Emitter<Events>,
  to: Emitter<Events>,
  events: readonly (keyof Events)[],
): Unsubscribe {
  const stops = [...new Set(events)].map((event) =>
    from.on(event, (payload) => {
      to.emit(event, payload);
    }),
  );
  return () => {
    for (const stop of stops) {
      stop();
    }
  };
}

/** The public interface of dashboard-events. */

export { Emitter } from "./emitter.ts";
export { EmitError } from "./errors.ts";
export { DASHBOARD_EVENTS, createDashboardBus } from "./events.ts";
export type { DashboardEvents } from "./events.ts";
export { forward } from "./forward.ts";
export type { EventMap, Listener, Unsubscribe } from "./types.ts";
export { WaitTimeoutError, waitFor } from "./wait.ts";

import assert from "node:assert/strict";
import { test } from "node:test";
import { Emitter } from "../src/emitter.ts";
import { DASHBOARD_EVENTS, createDashboardBus } from "../src/events.ts";
import { forward } from "../src/forward.ts";
import { WaitTimeoutError, waitFor } from "../src/wait.ts";

type Events = { saved: { id: string }; loaded: number };

test("waitFor resolves with the payload of the next emit", async () => {
  const bus = new Emitter<Events>();
  const next = waitFor(bus, "saved", 1000);
  bus.emit("saved", { id: "ops-main" });
  assert.deepEqual(await next, { id: "ops-main" });
});

test("waitFor removes its listener after the event came", async () => {
  const bus = new Emitter<Events>();
  const next = waitFor(bus, "loaded", 1000);
  assert.equal(bus.emit("loaded", 1), 1);
  await next;
  assert.equal(bus.emit("loaded", 2), 0);
});

test("waitFor rejects with WaitTimeoutError and removes its listener", async () => {
  const bus = new Emitter<Events>();
  await assert.rejects(waitFor(bus, "loaded", 20), {
    name: "WaitTimeoutError",
    message: 'no "loaded" event within 20 ms',
  });
  assert.equal(bus.emit("loaded", 1), 0);
  assert.ok(new WaitTimeoutError("x", 1) instanceof Error);
});

test("forward re-emits the listed events on the other bus", () => {
  const plugin = new Emitter<Events>();
  const dashboard = new Emitter<Events>();
  const seen: string[] = [];
  dashboard.on("saved", ({ id }) => seen.push(`saved ${id}`));
  dashboard.on("loaded", (rows) => seen.push(`loaded ${rows}`));
  forward(plugin, dashboard, ["saved", "saved"]);
  plugin.emit("saved", { id: "a" });
  plugin.emit("loaded", 3);
  assert.deepEqual(seen, ["saved a"]);
});

test("the function forward returns stops forwarding", () => {
  const plugin = new Emitter<Events>();
  const dashboard = new Emitter<Events>();
  let count = 0;
  dashboard.on("loaded", () => {
    count += 1;
  });
  const stop = forward(plugin, dashboard, ["loaded"]);
  plugin.emit("loaded", 1);
  stop();
  assert.equal(plugin.emit("loaded", 2), 0);
  assert.equal(count, 1);
});

test("the dashboard bus carries the dashboard events", () => {
  const bus = createDashboardBus();
  const kinds: string[] = [];
  bus.on("widget:added", ({ kind }) => kinds.push(kind));
  bus.emit("widget:added", { widgetId: "w1", kind: "chart" });
  assert.deepEqual(kinds, ["chart"]);
  assert.deepEqual(DASHBOARD_EVENTS, [
    "widget:added",
    "widget:removed",
    "layout:saved",
    "data:refreshed",
  ]);
});
